package com.hospital.platform.file.interfaces;
import com.hospital.platform.common.api.ApiResponse; import com.hospital.platform.common.security.AuthenticatedUser; import com.hospital.platform.common.trace.TraceId; import com.hospital.platform.file.application.FileStorageService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/v1/files") public class FileController { private final FileStorageService files; public FileController(FileStorageService files){this.files=files;} @PostMapping(consumes="multipart/form-data") @PreAuthorize("hasAuthority('system:file:upload')") public ApiResponse<FileStorageService.FileView> upload(@RequestPart MultipartFile file,@AuthenticationPrincipal AuthenticatedUser user)throws Exception{return ApiResponse.success(files.upload(file,user),TraceId.get());} @GetMapping("/{id}/url") @PreAuthorize("hasAuthority('system:file:read')") public ApiResponse<java.util.Map<String,String>> url(@PathVariable long id)throws Exception{return ApiResponse.success(java.util.Map.of("url",files.signedRead(id)),TraceId.get());}}
